// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2005,"grade":"8-11","contest":"Золотое руно","letters":"ДН?","count":60,"language":"ru","points":3,"tasksFile":"tasks-8-11.pdf","answersFile":"reviewed-8-11.pdf","sections":[{"start":1,"title":"Религии Востока"},{"start":6,"title":"Пророки и основатели религий"},{"start":11,"title":"Священные тексты"},{"start":16,"title":"Наставления"},{"start":21,"title":"Восток в русской литературе"},{"start":27,"title":"Восток в европейской музыке"},{"start":32,"title":"История"},{"start":43,"title":"Великие Моголы"},{"start":47,"title":"Архитектура"},{"start":52,"title":"Мифы Востока"},{"start":57,"title":"Высказывания о Востоке"}],"reviewedKey":true}, [{"question":"буддизм","context":"На рисунках изображены символы, характеризующие основные религии Востока. Подписи перепутаны. Укажите, какие из них сделаны верно, а какие нет.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Цветок в религии","figure":{"src":"assets/golden-fleece/2005/2005-01-lotus.webp","alt":"Розовато-жёлтый цветок с широкими лепестками на фоне зелёных листьев.","width":460,"height":460,"detailSrc":"assets/golden-fleece/2005/2005-01-lotus-large.webp"},"steps":["На фотографии цветок лотоса. Он растёт из илистого дна, а цветок поднимается над водой и остаётся чистым.","В буддийском искусстве лотос связан с чистотой, духовным пробуждением и изображениями Будды. Подпись подходит."]},{"question":"иудаизм","context":"На рисунках изображены символы, характеризующие основные религии Востока. Подписи перепутаны. Укажите, какие из них сделаны верно, а какие нет.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Чёрное святилище","figure":{"src":"assets/golden-fleece/2005/2005-02-kaaba.webp","alt":"Кубическое здание под чёрным покрывалом с золотой вышивкой, окружённое людьми.","width":420,"height":420,"detailSrc":"assets/golden-fleece/2005/2005-02-kaaba-large.webp"},"steps":["В центре толпы видно кубическое здание, покрытое чёрной тканью. Это Кааба в Мекке.","Мусульмане обращаются к Каабе во время молитвы и обходят её во время хаджа. Подпись «иудаизм» к этому снимку не подходит."]},{"question":"христианство","context":"На рисунках изображены символы, характеризующие основные религии Востока. Подписи перепутаны. Укажите, какие из них сделаны верно, а какие нет.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Крест с украшениями","figure":{"src":"assets/golden-fleece/2005/2005_03_big.jpg","alt":"Крест с золотой отделкой и цветными вставками.","width":200,"height":200},"steps":["У изображения есть поперечина и длинная вертикальная часть. Такая форма напоминает крест, на котором, по евангельскому рассказу, распяли Иисуса.","Крест стал одним из главных символов христианства. Подпись подходит."]},{"question":"ислам","context":"На рисунках изображены символы, характеризующие основные религии Востока. Подписи перепутаны. Укажите, какие из них сделаны верно, а какие нет.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Семь ветвей светильника","figure":{"src":"assets/golden-fleece/2005/2005_04_big.jpg","alt":"Схематический светильник с семью ветвями.","width":200,"height":200},"steps":["У изображения центральная стойка и по три ветви с каждой стороны. Так выглядит семисвечник, или менора.","Менора связана с Иерусалимским храмом и иудейской традицией. Подпись «ислам» ошибочна."]},{"question":"индуизм","context":"На рисунках изображены символы, характеризующие основные религии Востока. Подписи перепутаны. Укажите, какие из них сделаны верно, а какие нет.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Каменное колесо","figure":{"src":"assets/golden-fleece/2005/2005_05_big.jpg","alt":"Резное колесо со спицами на каменной стене.","width":200,"height":200},"steps":["На фотографии резное каменное колесо с массивной ступицей и орнаментом. Такие колёса образуют колесницу на стенах храма Солнца в Конараке.","Храм посвящён Сурье, божеству Солнца в индуизме. Этот памятник подходит к подписи «индуизм»."]},{"question":"Будда – реально существовавший человек.","context":"Религии Востока часто связывают с именами их основателей. Какие высказывания о них вы считаете верными?","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Исторический Будда","steps":["Будда означает «пробуждённый». Так называют Сиддхартху Гаутаму, учителя и основателя буддийской традиции.","Историки считают его реальным человеком, хотя точные годы его жизни остаются предметом исследования."]},{"question":"Мухаммед, основатель ислама, появился среди людей раньше Иисуса.","context":"Религии Востока часто связывают с именами их основателей. Какие высказывания о них вы считаете верными?","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Время основателей религий","steps":["Христианство связано с деятельностью Иисуса в I веке нашей эры. Мухаммед родился значительно позднее, примерно в 570 году.","Проповедь Мухаммеда относится к VII веку. Следовательно, в утверждении перепутана последовательность."]},{"question":"Кришна явился людям одним из проявлений бога Шивы.","context":"Религии Востока часто связывают с именами их основателей. Какие высказывания о них вы считаете верными?","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Кришна и божества","steps":["В индуистской традиции аватар — земное воплощение божества. В распространённом перечне аватаров Кришна относится к Вишну.","Поэтому утверждение о том, что Кришна был одним из проявлений Шивы, не согласуется с этим преданием."]},{"question":"Пророк иудаизма Моисей проповедовал полученные от Бога Законы на горе Синай.","context":"Религии Востока часто связывают с именами их основателей. Какие высказывания о них вы считаете верными?","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Моисей и Синай","steps":["В книге Исход Моисей поднимается на Синай, где Бог сообщает ему заповеди для народа.","Эпизод получения Закона именно там связан с Синаем. В задании оценивается содержание иудейского предания."]},{"question":"Иисус (согласно христианским верованиям) вознесся на небо на сороковой день после распятия.","context":"Религии Востока часто связывают с именами их основателей. Какие высказывания о них вы считаете верными?","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"От чего считают сорок дней","steps":["Согласно Деяниям апостолов, Иисус являлся ученикам после воскресения в течение сорока дней.","Христианский праздник Вознесения отсчитывают от Пасхи, то есть от воскресения. В тексте задания точкой отсчёта ошибочно названо распятие."]},{"question":"Тора, священная книга иудаизма, состоит из пяти первых книг Библии.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первые книги Библии","steps":["В узком смысле словом «Тора» называют Пятикнижие Моисеево. Оно включает Бытие, Исход, Левит, Числа и Второзаконие.","Это первые пять книг еврейской Библии и христианского Ветхого Завета. Утверждение о составе верно."]},{"question":"Коран, священная книга мусульман, был записан менее полутора тысяч лет назад.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Время записи Корана","steps":["Мухаммед проповедовал в начале VII века. Первые записи откровений появились в это же время, а ранний свод сложился после его смерти.","От VII до начала XXI века проходит около четырнадцати столетий. Это менее полутора тысяч лет."]},{"question":"Четыре христианских Евангелия были записаны апостолами Матфеем, Марком, Петром и Иоанном.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Авторы четырёх Евангелий","steps":["Канонические Евангелия названы по именам Матфея, Марка, Луки и Иоанна. Так их называет христианская традиция.","В предложенном списке вместо Луки указан Пётр. Это и делает утверждение неверным."]},{"question":"Основы индуизма изложены в Ведах – старинных священных текстах.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Веды","steps":["Веды — древнейшие священные сборники на ведийском санскрите, включающие гимны и ритуальные тексты.","У индуистских традиций есть и другие тексты, но Веды имеют основополагающий статус. Поэтому утверждение верно."]},{"question":"Основы буддизма изложены в великих индийских эпосах «Махабхарата» и «Рамаяна».","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Индийские эпосы","steps":["«Махабхарата» и «Рамаяна» — санскритские эпосы, тесно связанные с индуистской традицией. Герои «Рамаяны», например, Рама и Сита.","Основные ранние собрания буддийских текстов другие, в том числе палийская Типитака. Утверждение неверно."]},{"question":"Одна из заповедей Иисуса Христа гласит: «Не сотвори себе кумира».","context":"Священные тексты религиозных систем содержат нравственные наставления, широко распространенные во всем мире.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Запрет на кумира","steps":["Формулировка о кумире находится среди Десяти заповедей в книге Исход. В этом эпизоде Закон передан Моисею.","Вопрос предлагает приписать эту формулировку проповеди Иисуса. Для такого ответа нет основания в происхождении цитаты."]},{"question":"Один из 10 законов Моисея – «Возлюби ближнего своего как самого себя».","context":"Священные тексты религиозных систем содержат нравственные наставления, широко распространенные во всем мире.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Заповедь о ближнем","steps":["Исход и Второзаконие приводят два библейских перечня Десяти заповедей. В них этого изречения нет.","Его можно найти в книге Левит, а в Евангелии Иисус повторяет заповедь. Поэтому утверждение о её месте в Десяти заповедях неверно."]},{"question":"В Коране сказано: «И давайте сиротам их имущество и не заменяйте дурным хорошего».","context":"Священные тексты религиозных систем содержат нравственные наставления, широко распространенные во всем мире.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Слова об имуществе сирот","steps":["Указание возвращать сиротам их имущество находится в четвёртой суре Корана «Женщины». Вопрос воспроизводит смысл второго аята.","Продолжение предостерегает от присвоения имущества сирот. Цитата действительно относится к Корану."]},{"question":"Согласно книге «Исход», десять заповедей были записаны на десяти каменных скрижалях.","context":"Священные тексты религиозных систем содержат нравственные наставления, широко распространенные во всем мире.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Сколько было скрижалей","steps":["В книге «Исход» Моисей получает две каменные скрижали. На них находятся заповеди.","Число десять относится к заповедям. Каменных скрижалей было две, поэтому утверждение неверно."],"reviewedEdition":true},{"question":"Часто используемые слова «Многие знания – многие печали!» взяты из Библии.","context":"Священные тексты религиозных систем содержат нравственные наставления, широко распространенные во всем мире.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Фраза о знании","steps":["В начале книги Екклесиаста говорится, что умножающий познания умножает скорбь. Изречение передаёт мысль этого библейского стиха.","Фраза из задания является кратким пересказом Екклесиаста 1:18. Источник указан верно."]},{"question":"С небесной книги список дан\nТебе, пророк, не для строптивых;\nСпокойно возвещай Коран,\nНе понуждая нечестивых!\n\nЭти стихи написаны А. С. Пушкиным. Верно ли, что они написаны как подражание Корану?","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Пушкин и Коран","steps":["Упоминание пророка и Корана подсказывает, в каком пушкинском цикле искать строки.","Цитата входит в одно из стихотворений цикла «Подражания Корану». Его Пушкин написал в 1824 году."]},{"question":"Автор стихотворения «Ex oriente lux» Владимир Соловьёв написал и «Историю России с древнейших времён».","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Два Соловьёва","steps":["Владимир Сергеевич Соловьёв известен как философ и поэт. Строки о Востоке Ксеркса и Христа находятся в его стихотворении «Ex oriente lux».","«Историю России с древнейших времён» написал историк Сергей Михайлович Соловьёв, отец поэта."],"reviewedEdition":true},{"question":"Милльоны – вас. Нас тьмы, и тьмы, и тьмы.\nПопробуйте, сразитесь с нами!\nДа, скифы – мы! Да, азиаты – мы,\nС раскосыми и жадными очами!\n\nЭто стихи из стихотворения Александра Блока «Скифы». Верно ли, что они написаны в связи с Первой мировой войной?","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Когда написаны «Скифы»","steps":["Блок написал «Скифов» в январе 1918 года, когда Первая мировая война ещё продолжалась, а в Бресте шли мирные переговоры.","Обращение к Европе отражает размышления Блока в дни этих переговоров. С мировой войной стихотворение связано."]},{"question":"Помнит моя подоплека\nЖелтый Кашмир и Тибет\nВ шкуре овечьей востока\nТеплится жертвенный свет.\n\nАвтор этих стихов Николай Клюев. Верно ли, что он был старшим другом Есенина?","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Клюев и Есенин","steps":["Николай Клюев родился в 1884 году, Сергей Есенин — в 1895-м. Литературное общение поэтов началось в 1915 году.","Их связывали дружба и общий интерес к крестьянской культуре. Клюев действительно был старшим другом Есенина."]},{"question":"Он утих – и чудо совершилось:\nЧтобы снять алмаз они могли,\nИзваянье Будды преклонилось\nГоловой венчанной до земли.\n\nВерно ли, что автор этих стихов, Дмитрий Мережковский, был лауреатом Нобелевской премии?","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Нобелевская премия","steps":["Приведённый отрывок входит в стихотворение Мережковского «Будда». Вопрос касается награды, а не авторства.","Дмитрия Мережковского предлагали на Нобелевскую премию по литературе, но среди её лауреатов его нет. Номинация ещё не означает присуждение премии."]},{"question":"За работу над антологией «Поэзия Армении» Валерию Брюсову присвоили звание народного поэта Армении.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Почётное звание поэта","steps":["Брюсов редактировал антологию армянской поэзии и переводил для неё стихотворения на русский язык.","В 1923 году его удостоили звания народного поэта Армении за вклад в русско-армянские культурные связи."],"reviewedEdition":true},{"question":"Молодая красавица требует за свой танец голову Иоанна-Крестителя – «Семирамида».","context":"Мифы и легенды Востока, библейские сюжеты, археологические открытия XIX века будили воображение западноевропейских композиторов. Они стали искать новые музыкальные средства, которые смогли бы отразить колорит Востока, сплавить его сложный и непривычный для европейского уха музыкальный строй с традициями классической музыки. Так появились оперные шедевры Генделя («Тамерлан»), Моцарта («Похищение из сераля»), Россини («Семирамида»), Верди («Набукко»), Пуччини («Мадам Баттерфляй», «Турандот»), Р. Штрауса («Саломея»), Сен-Санса («Самсон и Далила»), Бизе («Искатели жемчуга»), Делиба («Лакме») и др.\n\nУкажите, правильно ли названы оперы (из числа упомянутых в тексте), в которых отражены следующие известные восточные сюжеты.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Танец и требование","steps":["Героиня танцует перед Иродом и добивается, чтобы ей принесли голову Иоанна Крестителя. Этот сюжет связан с именем Саломеи.","Оперу «Саломея» написал Рихард Штраус. «Семирамида» Россини рассказывает о вавилонской царице."]},{"question":"Восточная принцесса задает загадки претендентам на ее руку и велит отрубить голову тем, кто отвечает неправильно – «Турандот».","context":"Мифы и легенды Востока, библейские сюжеты, археологические открытия XIX века будили воображение западноевропейских композиторов. Они стали искать новые музыкальные средства, которые смогли бы отразить колорит Востока, сплавить его сложный и непривычный для европейского уха музыкальный строй с традициями классической музыки. Так появились оперные шедевры Генделя («Тамерлан»), Моцарта («Похищение из сераля»), Россини («Семирамида»), Верди («Набукко»), Пуччини («Мадам Баттерфляй», «Турандот»), Р. Штрауса («Саломея»), Сен-Санса («Самсон и Далила»), Бизе («Искатели жемчуга»), Делиба («Лакме») и др.\n\nУкажите, правильно ли названы оперы (из числа упомянутых в тексте), в которых отражены следующие известные восточные сюжеты.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Загадки принцессы","steps":["В опере принцесса отвечает согласием выйти замуж лишь за того, кто отгадает три загадки. Неверный ответ означает гибель претендента.","Этот сюжет лёг в основу оперы Джакомо Пуччини «Турандот». Название в условии указано верно."]},{"question":"Далила выведывает у Самсона тайну его силы, связанной с волосами, и отдаёт его в руки филистимлян — «Самсон и Далила».","context":"Мифы и легенды Востока, библейские сюжеты, археологические открытия XIX века будили воображение западноевропейских композиторов. Они стали искать новые музыкальные средства, которые смогли бы отразить колорит Востока, сплавить его сложный и непривычный для европейского уха музыкальный строй с традициями классической музыки. Так появились оперные шедевры Генделя («Тамерлан»), Моцарта («Похищение из сераля»), Россини («Семирамида»), Верди («Набукко»), Пуччини («Мадам Баттерфляй», «Турандот»), Р. Штрауса («Саломея»), Сен-Санса («Самсон и Далила»), Бизе («Искатели жемчуга»), Делиба («Лакме») и др.\n\nУкажите, правильно ли названы оперы (из числа упомянутых в тексте), в которых отражены следующие известные восточные сюжеты.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Далила и источник силы","steps":["Самсон возглавляет борьбу израильтян против филистимлян. Далила узнаёт его уязвимость и выдаёт героя противникам.","Самсон и Далила — главные герои одноимённой оперы Камиля Сен-Санса. Сюжет и название совпадают."],"reviewedEdition":true},{"question":"Незаконная дочь вавилонского царя добивается смертного приговора своей сестре и захватывает трон своего отца – «Саломея».","context":"Мифы и легенды Востока, библейские сюжеты, археологические открытия XIX века будили воображение западноевропейских композиторов. Они стали искать новые музыкальные средства, которые смогли бы отразить колорит Востока, сплавить его сложный и непривычный для европейского уха музыкальный строй с традициями классической музыки. Так появились оперные шедевры Генделя («Тамерлан»), Моцарта («Похищение из сераля»), Россини («Семирамида»), Верди («Набукко»), Пуччини («Мадам Баттерфляй», «Турандот»), Р. Штрауса («Саломея»), Сен-Санса («Самсон и Далила»), Бизе («Искатели жемчуга»), Делиба («Лакме») и др.\n\nУкажите, правильно ли названы оперы (из числа упомянутых в тексте), в которых отражены следующие известные восточные сюжеты.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Захват вавилонского трона","steps":["Претендентку на власть зовут Абигайль. Она распоряжается казнить Фенену, законную дочь вавилонского царя.","Эти героини действуют в опере «Набукко» Джузеппе Верди. «Саломея» посвящена другому сюжету."]},{"question":"Правительница Вавилона убивает своего мужа, выходит замуж за сына и погибает от его кинжала – «Набукко».","context":"Мифы и легенды Востока, библейские сюжеты, археологические открытия XIX века будили воображение западноевропейских композиторов. Они стали искать новые музыкальные средства, которые смогли бы отразить колорит Востока, сплавить его сложный и непривычный для европейского уха музыкальный строй с традициями классической музыки. Так появились оперные шедевры Генделя («Тамерлан»), Моцарта («Похищение из сераля»), Россини («Семирамида»), Верди («Набукко»), Пуччини («Мадам Баттерфляй», «Турандот»), Р. Штрауса («Саломея»), Сен-Санса («Самсон и Далила»), Бизе («Искатели жемчуга»), Делиба («Лакме») и др.\n\nУкажите, правильно ли названы оперы (из числа упомянутых в тексте), в которых отражены следующие известные восточные сюжеты.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Вавилонская царица","steps":["Сюжет о царице и возвращении её сына напоминает оперу Россини «Семирамида». Сын Ниния в ней скрывается под именем Арзаче.","В развязке Арзаче невольно убивает мать. «Набукко» Верди рассказывает о другом вавилонском сюжете."]},{"question":"Отец Александра Македонского — македонский царь Филипп II.","context":"Среди имен исторических деятелей, известных каждому человеку, имя Александра Македонского занимает одно из первых мест. Обдумайте суждения о нем и укажите, какие из них вы считаете верными.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Отец Александра","steps":["Александр вырос при дворе в Македонии. В это время царством правил Филипп II, расширивший его владения и влияние.","Филипп II был отцом Александра. После его смерти в 336 году до нашей эры Александр занял македонский престол."],"reviewedEdition":true},{"question":"Александр Македонский жил менее 2 000 лет тому назад.","context":"Среди имен исторических деятелей, известных каждому человеку, имя Александра Македонского занимает одно из первых мест. Обдумайте суждения о нем и укажите, какие из них вы считаете верными.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Когда жил полководец","steps":["Александр родился в 356 году до нашей эры и умер в 323 году до нашей эры.","Даже от начала нашей эры до времени конкурса прошло более двух тысяч лет. От эпохи Александра прошло ещё больше."]},{"question":"Александр Македонский в юности учился у Архимеда.","context":"Среди имен исторических деятелей, известных каждому человеку, имя Александра Македонского занимает одно из первых мест. Обдумайте суждения о нем и укажите, какие из них вы считаете верными.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Учитель Александра","steps":["Филипп II пригласил Аристотеля обучать юного Александра. Философ и будущий полководец были современниками.","Архимед родился уже после смерти Александра. Он не мог быть его наставником."],"reviewedEdition":true},{"question":"Александр Македонский умер, не дожив до 33 лет.","context":"Среди имен исторических деятелей, известных каждому человеку, имя Александра Македонского занимает одно из первых мест. Обдумайте суждения о нем и укажите, какие из них вы считаете верными.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Возраст Александра","steps":["Александр родился летом 356 года до нашей эры. Он умер в Вавилоне в июне 323 года до нашей эры.","До очередного дня рождения он не дожил. Ему было 32 года."]},{"question":"В результате походов Александра Македонского прекратила существование персидская держава Ахеменидов.","context":"Среди имен исторических деятелей, известных каждому человеку, имя Александра Македонского занимает одно из первых мест. Обдумайте суждения о нем и укажите, какие из них вы считаете верными.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Победа над Ахеменидами","steps":["Александр разбил армии Дария III при Иссе и Гавгамелах. Победы открыли ему путь к центрам Персидской державы.","Александр занял важнейшие города Ахеменидов. После смерти Дария их держава прекратила существование."],"reviewedEdition":true},{"question":"В своих походах Александр Македонский дошел до Индии.","context":"Среди имен исторических деятелей, известных каждому человеку, имя Александра Македонского занимает одно из первых мест. Обдумайте суждения о нем и укажите, какие из них вы считаете верными.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Поход к Инду","steps":["Армия Александра перешла Инд и в 326 году до н. э. сразилась у реки Гидасп с царём Пором.","Место битвы находится в исторической области Пенджаб. Античная Индия включала земли по Инду, ныне входящие в Пакистан."]},{"question":"Александр Македонский основал город Александрию на средиземноморском побережье Египта.","context":"Среди имен исторических деятелей, известных каждому человеку, имя Александра Македонского занимает одно из первых мест. Обдумайте суждения о нем и укажите, какие из них вы считаете верными.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Город на берегу Египта","steps":["Александр пришёл в Египет во время похода против Персидской державы. В 331 году до нашей эры он выбрал место для нового города.","Город получил имя Александрия и стал важным центром при династии Птолемеев."],"reviewedEdition":true},{"question":"В жизнеописании Александра Македонского у Плутарха его рождение отнесено к тому же дню, что и пожар храма Артемиды в Эфесе.","context":"Среди имен исторических деятелей, известных каждому человеку, имя Александра Македонского занимает одно из первых мест. Обдумайте суждения о нем и укажите, какие из них вы считаете верными.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Пожар храма Артемиды","steps":["Плутарх открывает жизнеописание Александра рассказами о происхождении героя. Среди них есть предание о храме Артемиды в Эфесе.","По этому преданию храм сгорел в день рождения Александра. Утверждение описывает содержание текста Плутарха."],"reviewedEdition":true},{"question":"Калаши живут в горных долинах Гиндукуша недалеко от города Читрал в Пакистане.","context":"Народы горных районов Южной Азии.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Где живут калаши","steps":["Калаши живут в долинах Бумбурет, Румбур и Бирир. Все три находятся в районе Читрал на севере Пакистана.","Эти долины лежат в горах Гиндукуша. Место в утверждении названо верно."],"adaptation":"В учебном вопросе уточняется, где живут калаши.","reviewedEdition":true},{"question":"В поэме Низами «Искандер-наме» Искандер — литературный образ Александра Македонского.","context":"Среди имен исторических деятелей, известных каждому человеку, имя Александра Македонского занимает одно из первых мест. Обдумайте суждения о нем и укажите, какие из них вы считаете верными.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Поэма об Искандере","steps":["В восточных литературных традициях имя Александр передают в форме Искандер. В названии поэмы эта форма стоит первой.","Низами опирался на предания об Александре Македонском и показал его как завоевателя и мудрого правителя."],"reviewedEdition":true},{"question":"Оно конечно, Александр Македонский герой, но зачем же стулья ломать? – слова смотрителя училищ в «Ревизоре» Гоголя.","context":"Среди имен исторических деятелей, известных каждому человеку, имя Александра Македонского занимает одно из первых мест. Обдумайте суждения о нем и укажите, какие из них вы считаете верными.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"История со стульями","steps":["В начале «Ревизора» городничий вспоминает учителя истории, который так увлёкся рассказом об Александре, что сломал стул.","Реплика принадлежит городничему. Смотритель училищ Лука Лукич слушает его и оправдывается."]},{"question":"Бабур, основатель державы Моголов, происходил по отцовской линии из рода Тимура.","context":"Бабур основал державу Моголов в Южной Азии в 1526 году. Могольская династия сохранялась до середины XIX века.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Происхождение Моголов","steps":["Тимур основал династию Тимуридов. Много поколений спустя к той же династии по отцовской линии принадлежал Бабур.","Бабур основал державу Моголов в Индии в XVI веке. Поэтому династическая связь с Тимуром указана верно."],"reviewedEdition":true},{"question":"Правление Моголов кончилось в 1707 г. со смертью последнего из Великих Моголов – Аурангзеба.","context":"Бабур основал державу Моголов в Южной Азии в 1526 году. Могольская династия сохранялась до середины XIX века.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Моголы после Аурангзеба","steps":["В 1707 году действительно умер Аурангзеб. После него империя постепенно теряла территории и власть.","На престоле остались императоры той же династии. Последний из них утратил власть только после восстания 1857 года."]},{"question":"Тадж-Махал в Агре был построен по приказу Бабура в память о Мумтаз-Махал.","context":"Бабур основал державу Моголов в Южной Азии в 1526 году. Могольская династия сохранялась до середины XIX века.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Кто заказал мавзолей","steps":["Мумтаз-Махал была супругой Шах-Джахана. После её смерти он распорядился возвести мавзолей в Агре.","Бабур основал державу Моголов примерно за век до строительства. Заказчиком Тадж-Махала был Шах-Джахан."],"reviewedEdition":true},{"question":"Великие Моголы были мусульмане.","context":"Бабур основал державу Моголов в Южной Азии в 1526 году. Могольская династия сохранялась до середины XIX века.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Вера правителей Моголов","steps":["Бабур, основатель династии, был мусульманином. Сохранившиеся мечети и мавзолеи показывают роль ислама при его преемниках.","В державе жили последователи разных религий, и политика императоров отличалась. Исторически династия была мусульманской."]},{"question":"Мечеть Бадшахи, Лахор","context":"Бабур основал державу Моголов в Южной Азии в 1526 году. Могольская династия сохранялась до середины XIX века.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Белый мавзолей","figure":{"src":"assets/golden-fleece/2005/2005_47_big.jpg","alt":"Белое здание с большим куполом, четырьмя минаретами и дорожкой по центру.","width":200,"height":200},"steps":["У здания белые стены и большой луковичный купол, а по углам стоят четыре минарета. К центральному входу ведёт длинная ось сада.","Это Тадж-Махал в Агре. Мечеть Бадшахи находится в Лахоре и выглядит иначе."]},{"question":"Тадж- -Махал, Агра","context":"Бабур основал державу Моголов в Южной Азии в 1526 году. Могольская династия сохранялась до середины XIX века.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Двор перед мечетью","figure":{"src":"assets/golden-fleece/2005/2005_48_big.jpg","alt":"Красный фасад с центральной аркой и белыми куполами за широким двором.","width":200,"height":200},"steps":["На фотографии красное здание с белыми куполами перед огромным двором. Главная арка выделяется на длинном симметричном фасаде.","Так выглядит Бадшахи, соборная мечеть Лахора. Тадж-Махал — мавзолей из белого мрамора в другом городе."]},{"question":"Ханский дворец, Джайпур","context":"Бабур основал державу Моголов в Южной Азии в 1526 году. Могольская династия сохранялась до середины XIX века.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Крепостные башни","figure":{"src":"assets/golden-fleece/2005/2005_49_big.jpg","alt":"Красные крепостные стены с зубцами и башнями на фоне зелени.","width":200,"height":200},"steps":["В кадре стены сложены из красного камня и укреплены выступающими башнями. Это характерный облик крепости.","Так выглядит Красный форт. Подпись о дворце в Джайпуре к изображению не подходит."]},{"question":"Мавзолей Хумаюна, Дели","context":"Бабур основал державу Моголов в Южной Азии в 1526 году. Могольская династия сохранялась до середины XIX века.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Купол и красные стены","figure":{"src":"assets/golden-fleece/2005/2005_50_big.jpg","alt":"Красно-белый мавзолей с большим светлым куполом на арочной платформе.","width":200,"height":200},"steps":["На фотографии красные стены с белыми деталями, высокий центральный вход и светлый купол. Здание поставлено на основание с рядом арок.","Эти признаки совпадают с мавзолеем Хумаюна в Дели. Подпись верна."]},{"question":"Красный форт, Дели","context":"Бабур основал державу Моголов в Южной Азии в 1526 году. Могольская династия сохранялась до середины XIX века.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Фасад за аркой","figure":{"src":"assets/golden-fleece/2005/2005_51_big.jpg","alt":"Светлый купольный фасад с несколькими этажами, видимый сквозь тёмную арку.","width":200,"height":200},"steps":["На снимке многоярусный дворцовый фасад с балконами и окнами. Его видно через тёмную арку.","Это дворцовая архитектура Джайпура. Красный форт Дели легко отличить по укреплённым стенам, как на соседнем снимке."]},{"question":"В индуистском искусстве Кришну часто изображают играющим на флейте.","context":"Изображения персонажей индийских мифов.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Музыка в индийском предании","steps":["Многие предания показывают Кришну мальчиком-пастухом. Его игра на флейте привлекает пастушек и стада.","Флейта стала характерным атрибутом Кришны. Поэтому утверждение о распространённом изображении верно."],"adaptation":"В учебной версии вопрос об изображениях Кришны заменяет задание с фотографией.","reviewedEdition":true},{"question":"Шива","context":"Среди громадного количества восточных мифов выделяются индийские мифы по обилию персонажей, увлекательных историй, красоте сохранившихся изображений. Упомянем пять мифологических фигур, которые вы должны будете распознать на рисунках: Брахма – создатель мира, Шива – созидатель и разрушитель в одном лице, Вишну – хранитель мира, Кришна – воплощение красоты, радости и любви, любимец детей Ганеша – покровитель учения.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Фигура под кобрами","figure":{"src":"assets/golden-fleece/2005/2005_52_big.jpg","alt":"Золотистая сидящая фигура под раскрытыми капюшонами змея.","width":200,"height":200},"steps":["Над сидящим божеством раскрывается капюшон многоголового змея. Такой навес в индийском искусстве часто образует змей Шеша.","С Шешей связывают фигуру Вишну. Для изображений Шивы более характерны трезубец, третий глаз и образ танцора."]},{"question":"На репродукции показан Брахма.","context":"Среди громадного количества восточных мифов выделяются индийские мифы по обилию персонажей, увлекательных историй, красоте сохранившихся изображений. Упомянем пять мифологических фигур, которые вы должны будете распознать на рисунках: Брахма – создатель мира, Шива – созидатель и разрушитель в одном лице, Вишну – хранитель мира, Кришна – воплощение красоты, радости и любви, любимец детей Ганеша – покровитель учения.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Танец в огненном кольце","figure":{"src":"assets/golden-fleece/2005/2005_55_big.jpg","alt":"Танцующая фигура в кольце пламени.","width":200,"height":200},"steps":["Фигура танцует с поднятой ногой внутри кольца пламени. Такой образ называют Натараджей, владыкой танца.","Натараджа — одно из изображений Шивы. Подпись с именем Брахмы к нему не подходит."],"reviewedEdition":true},{"question":"Ганеша","context":"Среди громадного количества восточных мифов выделяются индийские мифы по обилию персонажей, увлекательных историй, красоте сохранившихся изображений. Упомянем пять мифологических фигур, которые вы должны будете распознать на рисунках: Брахма – создатель мира, Шива – созидатель и разрушитель в одном лице, Вишну – хранитель мира, Кришна – воплощение красоты, радости и любви, любимец детей Ганеша – покровитель учения.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Несколько лиц","figure":{"src":"assets/golden-fleece/2005/2005_54_big.jpg","alt":"Многораменная сидящая статуэтка с несколькими лицами.","width":200,"height":200},"steps":["У изваяния видно несколько лиц. В таком виде нередко изображают Брахму, которого по преданию наделили четырьмя головами.","Ганешу узнают по голове слона. Подпись «Ганеша» к фигуре с человеческими лицами не подходит."]},{"question":"Вишну","context":"Среди громадного количества восточных мифов выделяются индийские мифы по обилию персонажей, увлекательных историй, красоте сохранившихся изображений. Упомянем пять мифологических фигур, которые вы должны будете распознать на рисунках: Брахма – создатель мира, Шива – созидатель и разрушитель в одном лице, Вишну – хранитель мира, Кришна – воплощение красоты, радости и любви, любимец детей Ганеша – покровитель учения.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Божество с хоботом","figure":{"src":"assets/golden-fleece/2005/2005_53_big.jpg","alt":"Каменный рельеф с фигурой с головой слона и хоботом.","width":200,"height":200},"steps":["На изображении различимы голова слона и длинный хобот. Это определяющие признаки Ганеши.","Вишну обычно изображают с человеческой головой, четырьмя руками и такими атрибутами, как диск и раковина. Подпись о Вишну ошибочна."]},{"question":"В первой строфе «Баллады о Востоке и Западе» Редьярд Киплинг говорит, что между двумя сильными людьми, встретившимися лицом к лицу, перестают действовать границы Востока и Запада.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Запад и Восток у Киплинга","steps":["Начало баллады разводит Восток и Запад. Следующие строки той же строфы описывают встречу двух людей, способных уважать друг друга.","Киплинг пишет, что в такой встрече различие между Востоком и Западом теряет силу. Поэтому утверждение верно."],"adaptation":"Учебный вопрос о конкретных строках первой строфы баллады.","reviewedEdition":true},{"question":"Слова «Восток – дело тонкое» произнесены одним из героев фильма «Бриллиантовая рука».","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Фраза из кино","steps":["Эту фразу произносит красноармеец Сухов, герой фильма Владимира Мотыля.","Фильм называется «Белое солнце пустыни». В условии названа другая картина."]},{"question":"«Панмонголизм! Хоть имя дико, но мне ласкает слух оно» – эти слова философа и поэта В. Соловьева взяты А. Блоком в качестве эпиграфа к поэме «Возмездие».","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Эпиграф Блока","steps":["Строки Владимира Соловьёва о панмонголизме Блок использовал как эпиграф. Сверим название по тексту произведения.","Эпиграф стоит перед стихотворением «Скифы». В задании вместо него указана поэма «Возмездие»."]},{"question":"Слова «Ex Oriente Lux» связывают со светом Вифлеемской звезды, появившейся при рождении Иисуса.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Свет с Востока","steps":["По-латыни ex Oriente lux означает «с Востока свет». В христианском толковании её связывают со звездой, которую волхвы увидели при рождении Иисуса.","Это одно из значений выражения. Им также обозначают роль восточных культур в истории человеческих знаний."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
